#!/usr/bin/env bash
# Step C - VARIANT 2: offline PSEUDO-LABEL incremental fine-tuning (v4 3D-box split).
#
#   Usage: bash tools_incremental/run_pseudo_v4.sh <3stage|6stage> [GPU_ID]
#
# Same warm-start backbone as the naive baseline (variant 1) but each stage t>1
# also trains on OLD-class pseudo-GT generated by the stage_{t-1} model, to fight
# catastrophic forgetting (SDCoT's offline-pseudo-label idea). Per stage:
#   * stage 1     : identical to naive (no old classes). Reused from the naive run
#                   if present (same cfg/data/seed -> identical), else trained.
#   * stage t > 1 : (a) expand_head prev->cumulative; (b) make_pseudo_labels.py:
#                   run stage_{t-1} model over stage-t TRAIN scenes, keep confident
#                   old-class dets -> *_pseudo.pkl (novel GT + old pseudo GT);
#                   (c) train on that pseudo pkl warm-started from the expanded
#                   head; (d) eval cumulative val.
# Out root: work_dirs/incremental_v4_pseudo_thr045/<sched>/stage{t}/. Idempotent: a stage
# with latest.pth + eval.log is skipped. Detached-friendly (setsid).
set -euo pipefail

ORDERING="${1:?usage: run_pseudo_v4.sh <3stage|6stage> [GPU_ID]}"
GPU_ID="${2:-0}"
REPO="$(cd "$(dirname "$0")/.." && pwd)"
PY="$REPO/venv/bin/python"
CFG_DIR="$REPO/configs/tr3d_incremental_v4/$ORDERING"
DATA_DIR="$REPO/data/sunrgbd_incremental/v4_3dbox/$ORDERING"
CARVE="$DATA_DIR/carve_report_v4.json"
OUT_ROOT="$REPO/work_dirs/incremental_v4_pseudo_thr045/$ORDERING"
SCORE_THR="${SCORE_THR:-0.45}"   # TR3D-recalibrated pseudo conf threshold (see make_pseudo_labels.py)
[ -d "$CFG_DIR" ] || { echo "no configs at $CFG_DIR"; exit 1; }

export CUDA_VISIBLE_DEVICES="$GPU_ID"   # -> only one visible device, local index 0
mapfile -t CFGS < <(ls "$CFG_DIR"/stage*.py | sort -V)
echo "=================================================================="
echo "[pseudo/$ORDERING] ${#CFGS[@]} stages | GPU=$GPU_ID | score_thr=$SCORE_THR | out=$OUT_ROOT"
echo "[pseudo/$ORDERING] started: $(date -Is)"
echo "=================================================================="

# Seed stage1 from the naive baseline if available (stage1 has no old classes, so
# the pseudo variant's stage1 is identical to naive's: same cfg, data, seed).
NAIVE_S1="$REPO/work_dirs/incremental_v4_naive/$ORDERING/stage1"
PSEUDO_S1="$OUT_ROOT/stage1"
if [ -e "$NAIVE_S1/latest.pth" ] && [ ! -e "$PSEUDO_S1/latest.pth" ]; then
  mkdir -p "$PSEUDO_S1"
  cp "$NAIVE_S1/latest.pth" "$PSEUDO_S1/latest.pth"
  [ -e "$NAIVE_S1/eval.log" ] && cp "$NAIVE_S1/eval.log" "$PSEUDO_S1/eval.log"
  echo "[seed] reused naive stage1 -> $PSEUDO_S1 (identical base, no old classes at stage1)"
fi

PREV_CKPT=""
PREV_CFG=""
for CFG in "${CFGS[@]}"; do
  STAGE="$(basename "$CFG" .py)"
  WORK_DIR="$OUT_ROOT/$STAGE"
  mkdir -p "$WORK_DIR"
  echo ""
  echo "######## [pseudo/$ORDERING/$STAGE] $(date -Is) ########"

  if [ -e "$WORK_DIR/latest.pth" ] && [ -e "$WORK_DIR/eval.log" ]; then
    echo "[skip] $STAGE already complete (latest.pth + eval.log present)"
    PREV_CKPT="$WORK_DIR/latest.pth"; PREV_CFG="$CFG"
    continue
  fi

  TRAIN_ARGS=("$CFG" --work-dir "$WORK_DIR" --seed 0 --deterministic)

  if [ "$STAGE" != "stage1" ]; then
    # (a) grow the classifier head to the new cumulative class count
    INIT="$WORK_DIR/init_expanded.pth"
    echo "[expand] $PREV_CKPT  ->  $INIT  (cfg=$CFG)"
    "$PY" "$REPO/tools_incremental/expand_head.py" --prev "$PREV_CKPT" --cfg "$CFG" --out "$INIT"

    # (b) generate old-class pseudo-GT from the stage_{t-1} model over this stage's TRAIN scenes
    TRAIN_PKL="$DATA_DIR/sunrgbd_infos_train_${STAGE}.pkl"
    PSEUDO_PKL="$WORK_DIR/sunrgbd_infos_train_${STAGE}_pseudo.pkl"
    echo "[pseudo] $PREV_CKPT (cfg=$PREV_CFG) over $TRAIN_PKL -> $PSEUDO_PKL  (score_thr=$SCORE_THR)"
    "$PY" "$REPO/tools_incremental/make_pseudo_labels.py" \
        --prev-cfg "$PREV_CFG" --prev-ckpt "$PREV_CKPT" \
        --train-pkl "$TRAIN_PKL" --carve-report "$CARVE" \
        --out-pkl "$PSEUDO_PKL" --raw-dets "$WORK_DIR/raw_dets.pkl" \
        --score-thr "$SCORE_THR" --gpu-id 0

    # (c) train on novel GT + old pseudo GT, warm-started from the expanded head
    TRAIN_ARGS+=(--cfg-options "load_from=$INIT" "data.train.dataset.ann_file=$PSEUDO_PKL")
  fi

  echo "[train] $PY tools/train.py ${TRAIN_ARGS[*]}"
  "$PY" "$REPO/tools/train.py" "${TRAIN_ARGS[@]}"

  PREV_CKPT="$WORK_DIR/latest.pth"; PREV_CFG="$CFG"
  [ -e "$PREV_CKPT" ] || { echo "ERROR: no checkpoint produced at $PREV_CKPT"; exit 2; }

  # (d) evaluate on the CUMULATIVE val set
  echo "[eval] cumulative val -> $WORK_DIR/eval.log + results.pkl"
  "$PY" "$REPO/tools/test.py" "$CFG" "$PREV_CKPT" \
      --out "$WORK_DIR/results.pkl" --eval mAP 2>&1 | tee "$WORK_DIR/eval.log"
done

echo ""
echo "[pseudo/$ORDERING] COMPLETE: $(date -Is)"
